import json

# Library to suppress warnings generated by your code:
import warnings

from langchain_openai import ChatOpenAI
from pathlib import Path

# Validation
from pydantic import BaseModel, Field, ValidationError
from typing import List, Optional

# Codes to suppress warnings generated by your code:
def warn(*args, **kwargs):
    pass
warnings.warn = warn
warnings.filterwarnings('ignore')

### Define the file_path to the text file
file_path = Path.home() / "food-chatbot-data" / "California-Culinary-Map.txt"

### Open the text file
with open(file_path) as text_file:
    text = text_file.read()

### Split the restaurant paragraphs into list
restaurant_list = text.split("\n\n")

### Since the first item is the dataset name, we remove it
restaurant_list = restaurant_list[1:]

### Print out the number of restaurants we have
print(len(restaurant_list))

### Print out the first item to have a closer look at the content
print(restaurant_list[0])

def llm_model(system_msg, prompt_txt):
    #system_msg: the system message given to the LLM
    #prompt_txt: the user prompt
    
    model_id = "qwen2.5:3b"

    api_key = "ollama"

    url = "http://localhost:11434/v1"

    ### Define the model by ModelInference
    model = ChatOpenAI(
            model = model_id,
            api_key = api_key,
            base_url = url
            )

    ### Define the messages
    messages = [
        {"role": "system", "content": system_msg},
        {"role": "user", "content": prompt_txt}
    ]

    ### Get the final response output and return it
    response = model.invoke(
        input = messages
        )
    return response.content

EXAMPLE_RESTAURANT_PARAGRAPH = restaurant_list[1] #use the second restaurant paragraph as the example
EXAMPLE_OUTPUT = """
    {{
    "name": "Mar de Cortez",
    "location": "Santa Monica",
    "type": "casual taqueria",
    "food_style": "Baja-style seafood",
    "rating": 4.2,
    "price_range": 1,
    "signatures": [
        "beer-battered snapper tacos",
        "zesty octopus ceviche"
    ],
    "vibe": "salt-air energy",
    "environment": "a premier sun-drenched spot for open-air dining near the pier."
    "shortcomings": []
    }}
"""

### Design your prompt here
def restaurant_data_structure_prompt_generation(restaurant_paragraph):
    base_system_msg = f"""
    RESPONSE FORMAT: Return ONLY a single JSON object—no markdown, no examples, no extra keys.

    Note: For the price range field, convert dollar signs (e.g., \\\\\$, $$, $$$) into an integer representing the number of dollar symbols.
    
    IMPORTANT: Your response must be *only* that JSON.  Do NOT include any illustrative or example JSON.
    """
    
    base_user_prompt = f"""
    Task:
    You are a JSON-only assistant.
    
    Transform input restaurant description into the required structured JSON format.

    Restaurant description:
    {restaurant_paragraph}

    Example:
    Input Restaurant Description: {EXAMPLE_RESTAURANT_PARAGRAPH}
    Output:
    {EXAMPLE_OUTPUT}
    
    """
    return base_system_msg, base_user_prompt

### Define the schema
class Restaurant(BaseModel):
    name: str
    location: str
    type: str
    food_style: str
    rating: Optional[float] = None
    price_range: Optional[int] = None
    signatures: List[str] = Field(default_factory=list)
    vibe: Optional[str] = None
    environment: str
    shortcomings: List[str] = Field(default_factory=list)

def JSON_auto_repair_prompts(candidate_json_output, error_message):
    auto_repair_system_msg = """
    RESPONSE FORMAT: Return ONLY a single JSON object—no markdown, no examples, no extra keys.

    Note: For the price range field, convert dollar signs (e.g., \\\\\$, $$, $$$) into an integer representing the number of dollar symbols.
    
    IMPORTANT: Your response must be *only* that JSON.  Do NOT include any illustrative or example JSON.
    """
    auto_repair_prompt = f"""
    Task:
    You are a JSON-only expert.
    
    Automatically repair and correct the original wrong candidate JSON output into the required structured JSON format with the guidance on correction from the error message generated by the schema validation if a mistake is detected.

    The original wrong candidate JSON output that does not conform to the required JSON format:
    {candidate_json_output}

    The guidance on correction from the error message generated by the schema validation if a mistake is detected:
    {error_message}
    """
    return auto_repair_system_msg, auto_repair_prompt

structured_restaurant_lists = []
for i, restaurant_paragraph in enumerate(restaurant_list):
    ### Produce your initial output
    base_system_msg, base_user_prompt = restaurant_data_structure_prompt_generation(restaurant_paragraph=restaurant_paragraph)
    candidate_json_output = llm_model(system_msg=base_system_msg, prompt_txt=base_user_prompt)

    ### Validation and Auto Correction loop on the output (while loop)
    while True:
        try:
            restaurant_data = Restaurant.model_validate_json(candidate_json_output)
            break
        except ValidationError as error_message:
            auto_repair_system_msg, auto_repair_prompt = JSON_auto_repair_prompts(candidate_json_output, error_message)
            candidate_json_output = llm_model(system_msg=auto_repair_system_msg, prompt_txt=auto_repair_prompt)

    ### Append your finalized response to the structured_restaurant_lists
    structured_restaurant_lists.append(candidate_json_output)

    # A manual progress bar
    if (i+1)%20 == 0:
        print(f'{i+1} out of {len(restaurant_list)} is done')

# A final message to notify the completion
print('ALL DONE!!')

structured_restaurant_lists_json = [json.loads(response) for response in structured_restaurant_lists]

#For each item in the restaurant list, assign it with an itemId to be consistent with the one in the user review data:
for i, response in enumerate(structured_restaurant_lists_json):
    response['itemId'] = 1000001 + i
    structured_restaurant_lists_json[i] = response
    
filename = Path.home() / "food-chatbot-data" / "structured_restaurant_data.json"
with open(filename, 'w', encoding='utf-8') as f:
    json.dump(structured_restaurant_lists_json, f, indent=4)